import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/embed%E7%94%A8%E3%81%AE%E3%82%B7%E3%82%A7%E3%83%AB%E3%81%AE%E3%82%88%E3%81%86%E3%81%AA%E4%BD%95%E3%81%8B.html","title":"embed用のシェルのような何か","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.48,"words":443},"filePathRelative":"embed用のシェルのような何か.md"}`),a={name:`embed用のシェルのような何か.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="embed用のシェルのような何か" tabindex="-1"><a class="header-anchor" href="#embed用のシェルのような何か"><span>embed用のシェルのような何か</span></a></h1><p>この場合のembedはアプリに組み込むという意味です。<a href="./Unix的.html">Unix的</a>, <a href="./Shell.html">Shell</a></p><p>シェルスクリプトは簡単だがアプリに組み込むのは面倒。この問題は定期的に考えている気がする。 そのうち名前をつけてまとめたい。</p><p><a href="./AshX.html">AshX</a>とか<a href="./GoFO.html">GoFO</a>とかは似た話に思う。</p><p>まぁいいとして、今回は、アプリの組み込み用のシェルっぽい何かのインタープリタがあったら使いたい気がする、という事から、 何が欲しいかを考えてみる。それはシェルの良さのようなものでもある。</p><h2 id="ポータブルで組み込みしやすいもの" tabindex="-1"><a class="header-anchor" href="#ポータブルで組み込みしやすいもの"><span>ポータブルで組み込みしやすいもの</span></a></h2><p>シェルが良くないのはポータビリティが低いのと、強力過ぎて組み込むのにいまいち、という所がある。 今回はシェルが欲しいのでは無く、シェルスクリプトの用に作っていきたい、というだけなので、互換性はいらない。 そしてポータブルであって欲しい。AndroidでもMacでもスクリプトの方は同じものが使いたい。</p><h2 id="シェルっぽく対話的に開発したい" tabindex="-1"><a class="header-anchor" href="#シェルっぽく対話的に開発したい"><span>シェルっぽく対話的に開発したい</span></a></h2><p>単に<a href="./Rhino.html">Rhino</a>を組み込むだけではどうだろう？<a href="./zx.html">zx</a>とかその中からリンクされてるdaxとかでは駄目か？ 今回は駄目としたい。</p><p>シェルっぽいとはどういう事か？</p><h3 id="エンターで行が実行される" tabindex="-1"><a class="header-anchor" href="#エンターで行が実行される"><span>エンターで行が実行される</span></a></h3><p>やはりエンターで実行されて欲しい。lsとかcdとかを確認しながらやっていきたい。C-jでもいいけれど、開始位置を指定はしたくない。</p><h3 id="入出力が文字列で行単位" tabindex="-1"><a class="header-anchor" href="#入出力が文字列で行単位"><span>入出力が文字列で行単位</span></a></h3><p>基本的には行単位でやっていきたい。</p><h3 id="普段の操作が出来る簡潔さ" tabindex="-1"><a class="header-anchor" href="#普段の操作が出来る簡潔さ"><span>普段の操作が出来る簡潔さ</span></a></h3><p>cdやlsやmvといった事が出来るくらいの簡潔さが欲しい。</p><h3 id="コマンドを作れる" tabindex="-1"><a class="header-anchor" href="#コマンドを作れる"><span>コマンドを作れる</span></a></h3><p>コマンドを何かしらの方法で作って、それを使って普段の作業が出来る、そのコマンドがスクリプトにも使える。</p><h2 id="nushell" tabindex="-1"><a class="header-anchor" href="#nushell"><span>Nushell</span></a></h2><p>Geminiにいろいろ相談していたらNushellに似てるのでは？と言われる。<a href="./Nushell.html">Nushell</a></p><h3 id="nushellと似たような文法のjsへのトランスパイラを書けないか" tabindex="-1"><a class="header-anchor" href="#nushellと似たような文法のjsへのトランスパイラを書けないか"><span>Nushellと似たような文法のJSへのトランスパイラを書けないか？</span></a></h3><p>embedでAndroidとPCで共通で使う事を思うと、nodeとRhinocsで動けばいいかなぁ、という気がする。 するとJSへのトランスパイラにならないかな？</p><p>以下をコンバートすると</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">ls *.md | where size &gt; 1000</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>JavaScriptでそれっぽくならんか。 以下になればいいか？</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">pipe(ls(undefined, &quot;*.md&quot;), (_in)=&gt;where(_in, _it=&gt;{_it.size &gt; 1000}))</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>型チェックとかは無くてもいいか。 pipeは一つめの結果を <code>in</code> 的なのに入れてwhereを呼び出す。</p><p>これだとwhereの実装がtableとlistとrecordを中で処理しないといけないのがだるいが。 まぁそのくらいはやればいいか。</p><p>なんかやれそうな気はするな。作ってみるか。</p><p>なんか<a href="./AshX.html">AshX</a>でも同じ事考えた気がするな。</p><h3 id="ashxの例を書けるか試してみる。" tabindex="-1"><a class="header-anchor" href="#ashxの例を書けるか試してみる。"><span>AshXの例を書けるか試してみる。</span></a></h3><p><a href="./AshX.html">AshX</a>では以下のようなのを書きたかったのだった。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token function">cdt</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// SAFでディレクトリを選ぶ</span></span>
<span class="line"><span class="token keyword">let</span> res <span class="token operator">=</span> <span class="token function">ls</span><span class="token punctuation">(</span><span class="token string">&quot;*.md&quot;</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token parameter">f</span><span class="token operator">=&gt;</span><span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">let</span> title <span class="token operator">=</span> <span class="token function">head</span><span class="token punctuation">(</span>f<span class="token punctuation">,</span> <span class="token punctuation">{</span><span class="token literal-property property">n</span><span class="token operator">:</span><span class="token number">1</span><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">replace</span><span class="token punctuation">(</span><span class="token string">&quot;^#¥s*&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;&quot;</span><span class="token punctuation">)</span></span>
<span class="line">            <span class="token keyword">let</span> date <span class="token operator">=</span> <span class="token function">basename</span><span class="token punctuation">(</span>f<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">replace</span><span class="token punctuation">(</span><span class="token string">&quot;-.*&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">replace</span><span class="token punctuation">(</span><span class="token string">&quot;_&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;&quot;</span><span class="token punctuation">)</span></span>
<span class="line">           <span class="token punctuation">[</span>title<span class="token punctuation">,</span> date<span class="token punctuation">,</span> f<span class="token punctuation">]</span></span>
<span class="line">         <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">         <span class="token punctuation">.</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span>res<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token function">open</span><span class="token punctuation">(</span>res<span class="token punctuation">.</span>path<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>user cdとuser selectというコマンドと、editorというコマンドがあったとすると、だいたい以下みたいな感じか。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">user cd</span>
<span class="line">ls *.md | each {|f| </span>
<span class="line">    let title = open --raw $f | lines | first | str replace -r &#39;# *&#39; &#39;&#39;</span>
<span class="line">    let date = $f.name | str replace -r &#39;-.*&#39; &#39;&#39; |  str replace -r &#39;_&#39; &#39;&#39;</span>
<span class="line">    {title: $title, date: $date, file: $f}</span>
<span class="line">   }  | user select | get file | editor</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>JavaScriptとしては以下か？</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">user(undefined, &quot;cd&quot;)</span>
<span class="line">pipe(ls(undefined, &quot;*.md&quot;), (_in)=&gt;{ each(_in, (f)=&gt; {</span>
<span class="line">      let title = pipe(pipe(pipe(open(undefined, &quot;--raw&quot;, f), (_in)=&gt;{ lines(_in) }), (_in)=&gt;{first(_in)}), (_in)=&gt;{str(_in, &quot;replace&quot;, &#39;-r&#39;, &#39;#*&#39;, &#39;&#39;) })))</span>
<span class="line">      //以下略</span>
<span class="line">      return {title: title, date: date, file: f, tag: &quot;record&quot;}</span>
<span class="line">   })</span>
<span class="line">})</span>
<span class="line">// 以下略</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>やれない事も無さそうか。フラグは文字列じゃなくて引数で渡すっぽいので <code>{_in: ..., flags: {raw: true}}</code> とかを渡す方がいいかもしれん。</p><p>サブコマンドは無くてもいいような気はするなぁ。</p><p>でもなんか元のJSと比べてそんなに楽になってないような気もするなぁ。</p><p>Nushellと似ているだけで違うものとしよう。ユーザーのUIが絡むものをui_のプレフィクスをつける。 openしてlinesは面倒なのでread_linesにする。str replaceはreplaceにして基本正規表現とする。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">ui_cd</span>
<span class="line">ls *.md | each {|f| </span>
<span class="line">    let title = read_lines $f | first | replace &#39;# *&#39; &#39;&#39;</span>
<span class="line">    let date = $f.name | replace &#39;-.*&#39; &#39;&#39; |  replace &#39;_&#39; &#39;&#39;</span>
<span class="line">    {title: $title, date: $date, file: $f}</span>
<span class="line">   }  | ui_select | get file | ui_editor</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>割といいのでは？</p><p><a href="./TypeScript.html">TypeScript</a>で実装するか？</p><p><a href="./型システム.html">型システム</a></p>`,45)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};